/bin/bash -lc "node - <<'NODE'
const fs = require('fs');
for (const path of ['/home/user/.config/google-chrome/Local State','/home/user/.config/google-chrome/Default/Preferences']) {
  const data = JSON.parse(fs.readFileSync(path, 'utf8'));
  console.log('\\n' + path);
  if (path.endsWith('Local State')) {
    console.log(JSON.stringify({profile: data.profile}, null, 2));
  } else {
    console.log(JSON.stringify({account_info: data.account_info, profile: data.profile, signin: data.signin}, null, 2));
  }
}
NODE"

