item.command:
/bin/bash -lc "pkill -TERM -x chrome || true
sleep 2
pgrep -x chrome >/dev/null && pkill -KILL -x chrome || true
node - <<'NODE'
const fs = require('fs');
const paths = {
  localState: '/home/user/.config/google-chrome/Local State',
  prefs: '/home/user/.config/google-chrome/Default/Preferences',
};
const target = 'Thomas';
for (const path of Object.values(paths)) {
  fs.copyFileSync(path, "'`${path}.bak-before-thomas-profile-name`);
}
const local = JSON.parse(fs.readFileSync(paths.localState, '"'utf8'));
local.profile ??= {};
local.profile.info_cache ??= {};
local.profile.info_cache.Default ??= {};
Object.assign(local.profile.info_cache.Default, {
  name: target,
  is_using_default_name: false,
});
fs.writeFileSync(paths.localState, JSON.stringify(local));

const prefs = JSON.parse(fs.readFileSync(paths.prefs, 'utf8'));
prefs.profile ??= {};
prefs.profile.name = target;
prefs.profile.using_default_name = false;
fs.writeFileSync(paths.prefs, JSON.stringify(prefs));
console.log('Updated Chrome Default profile name to Thomas.');
NODE
